<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">PTE </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">=</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;"> AccessMemory</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(PTEAddr)</span></span>
